//! Erasure coding for Neoblast segments.
//!
//! The code is Reed-Solomon over GF(2^16) using the Leopard-RS **high-rate**
//! algorithm (decision 0006). `reed-solomon-simd` 3.1.0 provides it; its output is
//! byte-identical to the original Leopard-RS C library, which the
//! `leopard_fixtures` test checks on every run against fixtures generated by
//! `tools/leopard-vectors/`.
//!
//! Two rules keep the bytes stable and Leopard-compatible:
//!
//! * the high-rate encoder and decoder are always used. The crate's automatic
//!   rate choice produces different parity for some k/n (for example 10-of-50);
//! * shard lengths are multiples of 64 bytes.
//!
//! `reed-solomon-simd` has a small blast radius (8 reverse dependencies on
//! crates.io, Oct 2026), so it sits behind the [`ErasureCode`] trait and is pinned
//! to an exact version.
//!
//! All functions take k, n and shard length from a validated header, never from
//! a peer (code-review issue 1). Callers pass only shards they have already
//! checked against the manifest's hashes (issue 2).
#![cfg_attr(test, allow(clippy::unwrap_used, clippy::expect_used, clippy::panic))]

use std::collections::BTreeMap;

use reed_solomon_simd::engine::DefaultEngine;
use reed_solomon_simd::rate::{HighRateDecoder, HighRateEncoder, RateDecoder, RateEncoder};
use thiserror::Error;

/// Shard lengths must be a multiple of this (decision 0006).
pub const SHARD_ALIGN: usize = 64;

/// Smallest supported k. For k = 1 `reed-solomon-simd` and Leopard-RS produce
/// different parity, so it is refused here as well as in the header (decision 0006).
pub const MIN_K: usize = 2;

/// Errors from encoding or reconstruction.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum ErasureError {
    /// k, n or the shard length are unusable.
    #[error("invalid parameters")]
    Params,
    /// Fewer than k shards are available.
    #[error("need {need} shards, have {have}")]
    NotEnough {
        /// Shards required (k).
        need: usize,
        /// Shards available.
        have: usize,
    },
    /// A shard has the wrong length.
    #[error("shard {0} has the wrong length")]
    ShardLength(usize),
    /// The underlying codec failed.
    #[error("codec error: {0}")]
    Codec(String),
}

/// A k-of-n erasure code over equal-length shards.
pub trait ErasureCode {
    /// Computes `recovery_count` parity shards from the original data shards,
    /// each as long as they are. Any other count or length is a
    /// [`ErasureError::Codec`] error for the functions below (review W-029).
    fn encode(
        &self,
        original: &[&[u8]],
        recovery_count: usize,
    ) -> Result<Vec<Vec<u8>>, ErasureError>;

    /// Restores missing original shards. Returns only the restored ones, keyed by index.
    /// A missing original the functions below need and do not get back, at the
    /// shards' length, is a [`ErasureError::Codec`] error for them (review W-029).
    fn restore(
        &self,
        original_count: usize,
        recovery_count: usize,
        original: &[(usize, &[u8])],
        recovery: &[(usize, &[u8])],
    ) -> Result<BTreeMap<usize, Vec<u8>>, ErasureError>;
}

/// Leopard-RS high-rate Reed-Solomon over GF(2^16), provided by
/// `reed-solomon-simd` 3.1.0.
#[derive(Clone, Copy, Debug, Default)]
pub struct ReedSolomonSimd;

fn codec(e: reed_solomon_simd::Error) -> ErasureError {
    ErasureError::Codec(e.to_string())
}

impl ErasureCode for ReedSolomonSimd {
    fn encode(
        &self,
        original: &[&[u8]],
        recovery_count: usize,
    ) -> Result<Vec<Vec<u8>>, ErasureError> {
        let shard_bytes = original.first().map_or(0, |s| s.len());
        // Decision 0006 rules hold for direct trait callers too, not only via
        // `encode_segment`.
        check_counts(original.len(), recovery_count, shard_bytes)?;
        let mut encoder = HighRateEncoder::new(
            original.len(),
            recovery_count,
            shard_bytes,
            DefaultEngine::new(),
            None,
        )
        .map_err(codec)?;
        for shard in original {
            encoder.add_original_shard(shard).map_err(codec)?;
        }
        let result = encoder.encode().map_err(codec)?;
        Ok(result.recovery_iter().map(<[u8]>::to_vec).collect())
    }

    fn restore(
        &self,
        original_count: usize,
        recovery_count: usize,
        original: &[(usize, &[u8])],
        recovery: &[(usize, &[u8])],
    ) -> Result<BTreeMap<usize, Vec<u8>>, ErasureError> {
        let shard_bytes = original
            .first()
            .or(recovery.first())
            .map_or(0, |(_, s)| s.len());
        check_counts(original_count, recovery_count, shard_bytes)?;
        if original.len() == original_count {
            return Ok(BTreeMap::new());
        }
        let mut decoder = HighRateDecoder::new(
            original_count,
            recovery_count,
            shard_bytes,
            DefaultEngine::new(),
            None,
        )
        .map_err(codec)?;
        for (i, shard) in original {
            decoder.add_original_shard(*i, shard).map_err(codec)?;
        }
        for (i, shard) in recovery {
            decoder.add_recovery_shard(*i, shard).map_err(codec)?;
        }
        let result = decoder.decode().map_err(codec)?;
        Ok(result
            .restored_original_iter()
            .map(|(i, s)| (i, s.to_vec()))
            .collect())
    }
}

/// Splits one segment's ciphertext into `n` shards of `shard_len` bytes:
/// `k` zero-padded data shards followed by `n - k` parity shards.
pub fn encode_segment(
    code: &impl ErasureCode,
    ciphertext: &[u8],
    k: usize,
    n: usize,
    shard_len: usize,
) -> Result<Vec<Vec<u8>>, ErasureError> {
    check(k, n, shard_len)?;
    let capacity = k.checked_mul(shard_len).ok_or(ErasureError::Params)?;
    if ciphertext.len() > capacity {
        return Err(ErasureError::Params);
    }
    let mut padded = ciphertext.to_vec();
    padded.resize(capacity, 0);
    let parity = encode_parity(code, &padded, k, n, shard_len)?;
    let mut shards: Vec<Vec<u8>> = padded.chunks_exact(shard_len).map(<[u8]>::to_vec).collect();
    shards.extend(parity);
    Ok(shards)
}

/// Computes the `n - k` parity shards of one segment whose `k` data shards lie
/// back to back in `data` (exactly `k * shard_len` bytes, already zero-padded).
///
/// Unlike [`encode_segment`], this makes no owned copy of the data shards:
/// callers hash and store `data.chunks_exact(shard_len)` directly. (The codec
/// still reads them into its own work buffer while encoding.)
pub fn encode_parity(
    code: &impl ErasureCode,
    data: &[u8],
    k: usize,
    n: usize,
    shard_len: usize,
) -> Result<Vec<Vec<u8>>, ErasureError> {
    check(k, n, shard_len)?;
    if Some(data.len()) != k.checked_mul(shard_len) {
        return Err(ErasureError::Params);
    }
    let shards: Vec<&[u8]> = data.chunks_exact(shard_len).collect();
    checked_parity(code, &shards, n, shard_len)
}

/// The codec's parity for `shards`, checked: `n - shards.len()` shards of
/// `shard_len` bytes each, or [`ErasureError::Codec`]. A codec that returns
/// anything else is broken, and saying so keeps the error from blaming the
/// store or the publisher (review W-029).
fn checked_parity(
    code: &impl ErasureCode,
    shards: &[&[u8]],
    n: usize,
    shard_len: usize,
) -> Result<Vec<Vec<u8>>, ErasureError> {
    let count = n.saturating_sub(shards.len());
    let parity = code.encode(shards, count)?;
    if parity.len() != count {
        return Err(ErasureError::Codec("wrong number of parity shards".into()));
    }
    if parity.iter().any(|s| s.len() != shard_len) {
        return Err(ErasureError::Codec(
            "parity shard of the wrong length".into(),
        ));
    }
    Ok(parity)
}

/// Rebuilds all `n` shards from any `k` verified ones.
///
/// `shards[i]` is `Some` for each shard the caller holds and has verified.
pub fn regenerate(
    code: &impl ErasureCode,
    k: usize,
    n: usize,
    shard_len: usize,
    shards: &[Option<Vec<u8>>],
) -> Result<Vec<Vec<u8>>, ErasureError> {
    let data = reconstruct_data(code, k, n, shard_len, shards)?;
    let refs: Vec<&[u8]> = data.iter().map(Vec::as_slice).collect();
    let parity = checked_parity(code, &refs, n, shard_len)?;
    let mut all = data;
    all.extend(parity);
    Ok(all)
}

/// Returns the `k` data shards, restoring any that are missing.
///
/// Any present shard whose length is not `shard_len` is an error, even when k
/// other shards would be enough: it means the caller has a bug or a bad header.
/// A missing data shard the codec does not restore, or restores at another
/// length, is [`ErasureError::Codec`] (review W-029).
pub fn reconstruct_data(
    code: &impl ErasureCode,
    k: usize,
    n: usize,
    shard_len: usize,
    shards: &[Option<Vec<u8>>],
) -> Result<Vec<Vec<u8>>, ErasureError> {
    check(k, n, shard_len)?;
    if shards.len() != n {
        return Err(ErasureError::Params);
    }
    let mut original = Vec::new();
    let mut recovery = Vec::new();
    for (i, shard) in shards.iter().enumerate() {
        if let Some(bytes) = shard {
            if bytes.len() != shard_len {
                return Err(ErasureError::ShardLength(i));
            }
            if i < k {
                original.push((i, bytes.as_slice()));
            } else {
                recovery.push((i.saturating_sub(k), bytes.as_slice()));
            }
        }
    }
    let have = original.len().saturating_add(recovery.len());
    if have < k {
        return Err(ErasureError::NotEnough { need: k, have });
    }
    let mut restored = code.restore(k, n.saturating_sub(k), &original, &recovery)?;
    (0..k)
        .map(|i| match shards.get(i) {
            Some(Some(bytes)) => Ok(bytes.clone()),
            _ => match restored.remove(&i) {
                Some(bytes) if bytes.len() == shard_len => Ok(bytes),
                Some(_) => Err(ErasureError::Codec(
                    "restored shard of the wrong length".into(),
                )),
                None => Err(ErasureError::Codec("missing shard not restored".into())),
            },
        })
        .collect()
}

fn check_counts(k: usize, m: usize, shard_len: usize) -> Result<(), ErasureError> {
    check(k, k.checked_add(m).ok_or(ErasureError::Params)?, shard_len)
}

fn check(k: usize, n: usize, shard_len: usize) -> Result<(), ErasureError> {
    if k < MIN_K || n <= k || shard_len == 0 || !shard_len.is_multiple_of(SHARD_ALIGN) {
        return Err(ErasureError::Params);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(64))]
        #[test]
        fn any_k_shards_rebuild_everything(
            data in proptest::collection::vec(any::<u8>(), 1..4000),
            k in MIN_K..12,
            extra in 1usize..12,
            seed in any::<u64>(),
        ) {
            let n = k + extra;
            let shard_len = data.len().div_ceil(k).div_ceil(SHARD_ALIGN) * SHARD_ALIGN;
            let code = ReedSolomonSimd;
            let shards = encode_segment(&code, &data, k, n, shard_len).unwrap();
            // Drop n - k shards chosen by the seed.
            let mut order: Vec<usize> = (0..n).collect();
            let mut s = seed;
            for i in (1..n).rev() {
                s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                order.swap(i, (s >> 33) as usize % (i + 1));
            }
            let mut held: Vec<Option<Vec<u8>>> = shards.iter().cloned().map(Some).collect();
            for &i in order.iter().take(n - k) {
                held[i] = None;
            }
            let rebuilt = regenerate(&code, k, n, shard_len, &held).unwrap();
            prop_assert_eq!(rebuilt, shards);
        }
    }

    #[test]
    fn too_few_shards_is_an_error_not_a_panic() {
        let code = ReedSolomonSimd;
        let shards = encode_segment(&code, b"abcdefgh", 2, 4, 64).unwrap();
        let held = vec![Some(shards[0].clone()), None, None, None];
        assert_eq!(
            reconstruct_data(&code, 2, 4, 64, &held),
            Err(ErasureError::NotEnough { need: 2, have: 1 })
        );
    }

    #[test]
    fn unaligned_shard_length_rejected() {
        // Decision 0006: only multiples of 64 are allowed.
        for len in [2, 3, 62, 66, 1000] {
            assert_eq!(
                encode_segment(&ReedSolomonSimd, b"abc", 2, 4, len),
                Err(ErasureError::Params)
            );
        }
    }

    #[test]
    fn trait_methods_enforce_the_rules_too() {
        let a = [7u8; 64];
        let odd = [7u8; 66];
        let code = ReedSolomonSimd;
        assert_eq!(code.encode(&[&a], 2), Err(ErasureError::Params)); // k = 1
        assert_eq!(code.encode(&[&odd, &odd], 2), Err(ErasureError::Params)); // not 64-aligned
        assert_eq!(code.encode(&[&a, &a], 0), Err(ErasureError::Params)); // no parity
        assert_eq!(
            code.restore(1, 2, &[], &[(0, &a)]),
            Err(ErasureError::Params)
        );
        assert_eq!(
            code.restore(2, 2, &[(0, &odd)], &[(0, &odd)]),
            Err(ErasureError::Params)
        );
        assert_eq!(code.encode(&[&a, &a], 2).map(|p| p.len()), Ok(2));
    }

    #[test]
    fn k_of_one_rejected() {
        // Decision 0006: k = 1 parity differs from Leopard-RS.
        assert_eq!(
            encode_segment(&ReedSolomonSimd, b"abc", 1, 3, 64),
            Err(ErasureError::Params)
        );
    }

    #[test]
    fn high_rate_is_used_even_where_the_default_rate_differs() {
        // 4-of-16: the crate's automatic choice would be low rate, whose parity
        // differs from Leopard-RS. Ours must equal the explicit high-rate encoder.
        let data: Vec<Vec<u8>> = (0..4u8).map(|i| vec![i.wrapping_mul(37); 64]).collect();
        let refs: Vec<&[u8]> = data.iter().map(Vec::as_slice).collect();
        let ours = ReedSolomonSimd.encode(&refs, 12).unwrap();
        let low = reed_solomon_simd::encode(4, 12, &refs).unwrap();
        assert_ne!(
            ours, low,
            "default rate is low here; ours must not follow it"
        );
        // Round trip with the high-rate decoder, losing all four originals.
        let recovery: Vec<(usize, &[u8])> = ours
            .iter()
            .enumerate()
            .take(4)
            .map(|(i, s)| (i, s.as_slice()))
            .collect();
        let restored = ReedSolomonSimd.restore(4, 12, &[], &recovery).unwrap();
        for (i, shard) in data.iter().enumerate() {
            assert_eq!(restored.get(&i), Some(shard));
        }
    }

    /// How [`Broken`] breaks the real codec's result.
    #[derive(Clone, Copy, Debug)]
    enum Fault {
        /// One shard fewer.
        Drop,
        /// One shard more.
        Extra,
        /// The last shard 64 bytes longer.
        Long,
        /// The last shard 64 bytes shorter.
        Short,
    }

    /// The real codec with one result broken (review W-029).
    struct Broken(Fault);

    fn break_last(fault: Fault, shard: &mut Vec<u8>) {
        match fault {
            Fault::Long => shard.extend([0u8; 64]),
            Fault::Short => shard.truncate(shard.len() - 64),
            Fault::Drop | Fault::Extra => {}
        }
    }

    impl ErasureCode for Broken {
        fn encode(
            &self,
            original: &[&[u8]],
            recovery_count: usize,
        ) -> Result<Vec<Vec<u8>>, ErasureError> {
            let mut parity = ReedSolomonSimd.encode(original, recovery_count)?;
            match self.0 {
                Fault::Drop => drop(parity.pop()),
                Fault::Extra => parity.push(parity[0].clone()),
                fault => break_last(fault, parity.last_mut().unwrap()),
            }
            Ok(parity)
        }

        fn restore(
            &self,
            original_count: usize,
            recovery_count: usize,
            original: &[(usize, &[u8])],
            recovery: &[(usize, &[u8])],
        ) -> Result<BTreeMap<usize, Vec<u8>>, ErasureError> {
            let mut restored =
                ReedSolomonSimd.restore(original_count, recovery_count, original, recovery)?;
            match self.0 {
                Fault::Drop => drop(restored.pop_last()),
                Fault::Extra => {
                    if let Some(first) = restored.values().next().cloned() {
                        restored.insert(original_count, first);
                    }
                }
                fault => {
                    if let Some(last) = restored.values_mut().last() {
                        break_last(fault, last);
                    }
                }
            }
            Ok(restored)
        }
    }

    /// W-029: a codec whose restore drops a shard is a `Codec` error, not
    /// `NotEnough` with enough shards held; one that restores a shard too
    /// long or too short is one too, not data of that length. An extra
    /// shard is not asked for, so only `regenerate`'s parity then fails.
    #[test]
    fn w029_a_broken_restore_is_a_codec_error() {
        let shards = encode_segment(&ReedSolomonSimd, b"abcdefgh", 2, 4, 64).unwrap();
        let held = vec![None, Some(shards[1].clone()), Some(shards[2].clone()), None];
        assert!(reconstruct_data(&ReedSolomonSimd, 2, 4, 64, &held).is_ok());
        assert!(regenerate(&ReedSolomonSimd, 2, 4, 64, &held).is_ok());
        for fault in [Fault::Drop, Fault::Long, Fault::Short] {
            assert!(
                matches!(
                    reconstruct_data(&Broken(fault), 2, 4, 64, &held),
                    Err(ErasureError::Codec(_))
                ),
                "{fault:?}"
            );
        }
        for fault in [Fault::Drop, Fault::Extra, Fault::Long, Fault::Short] {
            assert!(
                matches!(
                    regenerate(&Broken(fault), 2, 4, 64, &held),
                    Err(ErasureError::Codec(_))
                ),
                "{fault:?}"
            );
        }
    }

    /// W-029: parity of the wrong count, or whose last shard is too long or
    /// too short, is a `Codec` error, from `encode_segment` and from
    /// `regenerate`, which encodes after restoring.
    #[test]
    fn w029_broken_parity_is_a_codec_error() {
        let shards = encode_segment(&ReedSolomonSimd, b"abcdefgh", 2, 4, 64).unwrap();
        // Both data shards held: nothing to restore, so only the parity breaks.
        let held = vec![Some(shards[0].clone()), Some(shards[1].clone()), None, None];
        assert!(regenerate(&ReedSolomonSimd, 2, 4, 64, &held).is_ok());
        for fault in [Fault::Drop, Fault::Extra, Fault::Long, Fault::Short] {
            assert!(
                matches!(
                    encode_segment(&Broken(fault), b"abcdefgh", 2, 4, 64),
                    Err(ErasureError::Codec(_))
                ),
                "{fault:?}"
            );
            assert!(
                matches!(
                    regenerate(&Broken(fault), 2, 4, 64, &held),
                    Err(ErasureError::Codec(_))
                ),
                "{fault:?}"
            );
        }
    }
}
